"use strict";(self.webpackChunkportfolio=self.webpackChunkportfolio||[]).push([[8453],{23393:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>l,contentTitle:()=>a,default:()=>d,frontMatter:()=>o,metadata:()=>s,toc:()=>c});const s=JSON.parse('{"id":"technologies/interviewPrep/design_principles/SOLID/DependencyInversionPrinciple/cSharp/readme","title":"C# Example","description":"Example","source":"@site/docs/technologies/interviewPrep/design_principles/SOLID/DependencyInversionPrinciple/cSharp/readme.md","sourceDirName":"technologies/interviewPrep/design_principles/SOLID/DependencyInversionPrinciple/cSharp","slug":"/technologies/interviewPrep/design_principles/SOLID/DependencyInversionPrinciple/cSharp/","permalink":"/docs/technologies/interviewPrep/design_principles/SOLID/DependencyInversionPrinciple/cSharp/","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/technologies/interviewPrep/design_principles/SOLID/DependencyInversionPrinciple/cSharp/readme.md","tags":[],"version":"current","frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"Dependency Inversion Principle (DIP)","permalink":"/docs/technologies/interviewPrep/design_principles/SOLID/DependencyInversionPrinciple/"},"next":{"title":"JavaScript Example","permalink":"/docs/technologies/interviewPrep/design_principles/SOLID/DependencyInversionPrinciple/javascript/"}}');var r=i(74848),t=i(28453);const o={},a="C# Example",l={},c=[];function p(e){const n={code:"code",h1:"h1",header:"header",pre:"pre",...(0,t.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"c-example",children:"C# Example"})}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-csharp",children:'/*\nDependency Inversion Principle\n\n- high level parts of the system should not depend on low level parts of the system directly\n- high level parts of the system should depend on some kind of abstraction\n*/\n\nusing System.Collections.Generic;\nusing System.Linq;\n\npublic enum Relationship {\n  Parent,\n  Child,\n  Sibling\n}\n\npublic class Person {\n  public string Name;\n  public System.DateTime DateOfBirth;\n}\n\n// low level\n/*\npublic class Relationships {\n  // tuples\n  // this is a bad example as Relationships cannot change how it stores data, and the data structure is exposed to the high level module\n  private List<(Person, Relationship, Person)> _relations = new List<(Person, Relationship, Person)> ();\n\n  public void AddParentAndChild(Person parent, Person child) {\n    _relations.Add((parent, Relationship.Parent, child));\n    _relations.Add((child, Relationship.Child, parent));\n  }\n\n  // this is bad and should be removed\n  public List<(Person, Relationship, Person)> Relations => _relations;\n}\n*/\n\n\n// Solution\n// create an interface\npublic interface IRelationshipBrowser {\n  IEnumerable<Person> FindAllChildrenOf(string name);\n}\n\n// low level\npublic class Relationships : IRelationshipBrowser {\n  // tuples\n  // relationships can change the underlying data structure because it\'s never exposed to the high level modules which are actually consuming it\n  private List<(Person, Relationship, Person)> _relations = new List<(Person, Relationship, Person)> ();\n\n  public void AddParentAndChild(Person parent, Person child) {\n    _relations.Add((parent, Relationship.Parent, child));\n    _relations.Add((child, Relationship.Child, parent));\n  }\n\n  public IEnumerable<Person> FindAllChildrenOf(string name) {\n    return _relations.Where(\n          x => x.Item1.Name == "John" &&\n          x.Item2 == Relationship.Parent\n          ).Select(r => r.Item3);\n  }\n}\n\n// High level\n// should not depend on low level, but rather an abstraction, in this case Interface\npublic class Research {\n  // do not do this as it depends on the low level module\n  /*\n  public Research(Relationships relationships) {\n    var relations = relationships.Relations;\n    foreach (var r in relations.Where(\n          x => x.Item1.Name == "John" &&\n          x.Item2 == Relationship.Parent\n          )) {\n      System.Console.WriteLine($"John has a child called {r.Item3.Name}");\n    }\n  }\n  */\n\n  // do this as it depends on the abstraction, interface\n  public Research(IRelationshipBrowser browser) {\n    foreach (var p in browser.FindAllChildrenOf("John"))\n      System.Console.WriteLine($"John has a child called {p.Name}");\n  }\n\n  public static void Main() {\n    Person parent = new Person {Name = "John"};\n    Person child1 = new Person {Name = "Chris"};\n    Person child2 = new Person {Name = "Mary"};\n\n    Relationships relationships = new Relationships();\n    relationships.AddParentAndChild(parent, child1);\n    relationships.AddParentAndChild(parent, child2);\n\n    new Research(relationships);\n  }\n}\n'})})]})}function d(e={}){const{wrapper:n}={...(0,t.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(p,{...e})}):p(e)}},28453:(e,n,i)=>{i.d(n,{R:()=>o,x:()=>a});var s=i(96540);const r={},t=s.createContext(r);function o(e){const n=s.useContext(t);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:o(e.components),s.createElement(t.Provider,{value:n},e.children)}}}]);